nodes.detail:
使用哈希表记录已遍历数字及其下标，检查目标值与当前值的差是否已经出现，找到后立即返回下标。

package main

import (
	"bufio"
	"fmt"
	"os"
)

func slove(nums []int, target int) []int {
	set := make(map[int]int, len(nums))
	for i, v := range nums {
		if j, ok := set[target-v]; ok {
			//找到就直接返回
			return []int{j, i}
		}
		set[v] = i
	}
	//全部遍历完没有的话返回nil
	return nil
}
func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	if _, err := fmt.Fscan(in, &n); err != nil {
		return
	}
	nums := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &nums[i])
	}
	var target int
	fmt.Fscan(in, &target)
	ans := slove(nums, target)
	if len(ans) == 2 {
		fmt.Printf("%d, %d\n", ans[0], ans[1])
	}
}


时间复杂度：O(n)；空间复杂度：O(n)。

