nodes.detail:
将每个字符串排序后得到规范化键，相同键的字符串归入同一组。

package main

import (
	"bufio"
	"os"
	"fmt"
	"sort" // 修复：导入 sort 包
)

func slove(strs []string) [][]string {
	ans := make([][]string, 0)
	set := make(map[string][]string) 
	for _, s := range strs {         
		s_sort := sortstring(s) 
		set[s_sort] = append(set[s_sort], s)
	}
	for _, v := range set { 
		ans = append(ans, v)
	}
	return ans
}

func sortstring(s string) string {
	b := []byte(s)
	sort.Slice(b, func(i, j int) bool { //sort.Slice 没有返回值
		return b[i] < b[j] // 直接return比较结果
	})
	return string(b)
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	if _,err := fmt.Fscan(in,&n); err != nil{
		return
	}
	strs := make([]string,n)
	for i:=0;i<n;i++{
		fmt.Fscan(in,&strs[i])
	}
	ans := slove(strs)
	for i:=0;i<len(ans);i++{
		for j:=0;j<len(ans[i]);j++{
			fmt.Print(ans[i][j], " ") 
		}
		fmt.Println()
	}


}


设总字符数为 N、单词最大长度为 k：时间复杂度 O(N log k)；空间复杂度 O(N)。

