nodes.detail:
将数字放入集合，只从连续序列起点向后扫描，避免重复计算序列长度。

package main
import (
	"fmt"
	"bufio"
	"os"
)

func slove(nums []int) int {
	set := make(map[int]bool,len(nums))
	bestlen := 0
	for _, v := range nums {
		set[v] = true
	}
	for _, v := range nums {
		//注意是前面有的话就continue
		if set[v-1] {
			continue
		}
		curlen := 1
		cur := v
		for set[cur+1] {
			cur++
			curlen++
		}
		bestlen = max(bestlen,curlen)
	}
	return bestlen

}


func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	if _, err := fmt.Fscan(in, &n); err != nil {
		return 
	}
	nums := make([]int,n)
	for i:=0;i<n; i++{
		fmt.Fscan(in, &nums[i])
	}
	ans := slove(nums)
	fmt.Println(ans)

}


时间复杂度：O(n)（均摊）；空间复杂度：O(n)。

