nodes.detail:
先用哈希表为每个原节点创建副本，再根据映射连接 Next 和 Random 指针，完成深拷贝。

package main

import (
	"bufio"
	"fmt"
	"os"
)

type Node struct {
	Val    int
	Next   *Node
	Random *Node
}

func slove(head *Node) *Node {
	set := make(map[*Node]*Node)
	for cur := head; cur != nil; cur = cur.Next {
		set[cur] = &Node{Val: cur.Val}
	}
	for cur := head; cur != nil; cur = cur.Next {
		set[cur].Next = set[cur.Next]
		set[cur].Random = set[cur.Random]
	}
	return set[head]
}

// 注意这里的构建方法比较特殊
func bulidlist(in *bufio.Reader, n int) *Node {
	if n == 0 {
		return nil
	}
	nodes := make([]*Node, n)
	randIdx := make([]int, n)

	for i := 0; i < n; i++ {
		var val, r int
		fmt.Fscan(in, &val, &r)
		nodes[i] = &Node{Val: val}
		//r 是 random 指针指向的节点下标
		randIdx[i] = r
	}

	for i := 0; i < n; i++ {
		if i+1 < n {
			nodes[i].Next = nodes[i+1]
		}
		//一定记得要先判断这个节点random指向node的第几个节点,也就是randIdx[i],如果是-1就跳过不连接了
		if randIdx[i] != -1 {
			nodes[i].Random = nodes[randIdx[i]]
		}
	}
	return nodes[0]
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	if _, err := fmt.Fscan(in, &n); err != nil {
		return
	}
	head := bulidlist(in, n)
	ans := slove(head)

	for cur := ans; cur != nil; cur = cur.Next {
		//r=-1代表着这个节点random指向nil
		r := -1
		if cur.Random != nil {
			r = cur.Random.Val
		}
		fmt.Printf("%d %d\n", cur.Val, r)
	}
}


时间复杂度：O(n)；空间复杂度：O(n)。

