func findAnagramsReference(s string, p string) []int {
	if len(p) > len(s) {
		return nil
	}
	need := [26]int{}
	window := [26]int{}
	for i := 0; i < len(p); i++ {
		need[p[i]-'a']++
		window[s[i]-'a']++
	}
	ans := make([]int, 0)
	if need == window {
		ans = append(ans, 0)
	}
	for i := len(p); i < len(s); i++ {
		window[s[i]-'a']++
		window[s[i-len(p)]-'a']--
		if need == window {
			ans = append(ans, i-len(p)+1)
		}
	}
	return ans
}

