			fmt.Print(v)
		}
		fmt.Println()
	}
}

func setZeroesReference(matrix [][]int) {
	rows, cols := len(matrix), len(matrix[0])
	firstColZero := false
	for i := 0; i < rows; i++ {
		if matrix[i][0] == 0 {
			firstColZero = true
		}
		for j := 1; j < cols; j++ {
			if matrix[i][j] == 0 {
				matrix[i][0] = 0
				matrix[0][j] = 0
			}
		}
	}
	for i := rows - 1; i >= 0; i-- {
		for j := cols - 1; j >= 1; j-- {
			if matrix[i][0] == 0 || matrix[0][j] == 0 {
				matrix[i][j] = 0
			}
		}
		if firstColZero {
			matrix[i][0] = 0
		}
	}
}

