func nextPermutationReference(nums []int) {
	i := len(nums) - 2
	for i >= 0 && nums[i] >= nums[i+1] {
		i--
	}
	if i >= 0 {
		j := len(nums) - 1
		for nums[j] <= nums[i] {
			j--
		}
		nums[i], nums[j] = nums[j], nums[i]
	}
	reverseReference(nums, i+1, len(nums)-1)
}

func reverseReference(nums []int, left int, right int) {
	for left < right {
		nums[left], nums[right] = nums[right], nums[left]
		left++
		right--
	}
}

使用 prev、cur、next 三个指针迭代反转 Next 指针，最后返回新的头节点。

package main

import (
	"bufio"
	"fmt"
	"os"
)
type Node struct {
	Val int
	Next *Node
}

func slove(head *Node) *Node {
	var prev *Node
	cur := head                                                          
	for cur != nil {
		next := cur.Next
		cur.Next = prev                           
		prev = cur
		cur = next
	}
	return prev
}

func bulidlist(in *bufio.Reader, n int) *Node {
	if n == 0 {
		return nil
	}
	head := &Node{}
	cur := head
	for i:=0; i<n; i++ {
		fmt.Fscan(in, &cur.Val)
		if i+1<n {
			cur.Next = &Node{}
			cur = cur.Next
		}
	}
	return head
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	if _, err := fmt.Fscan(in, &n);err!=nil{
		return
	}

	head := bulidlist(in,n)
	head = slove(head)

	for cur:=head; cur!=nil; cur= cur.Next {
		fmt.Printf("%d\n",cur.Val)
	}
}

时间复杂度：O(n)；空间复杂度：O(1)。

