使用虚拟头节点和尾指针，每次选取两个链表当前较小节点接到结果尾部，最后拼接剩余部分。

package main
import (
	"fmt"
	"os"
	"bufio"
)
type Node struct {
	Val int
	Next *Node
}
func bulidlist(in *bufio.Reader, n int) *Node {
	if n==0 {
		return nil
	}
	head := &Node{}
	cur := head
	for i:=0; i<n; i++ {
		fmt.Fscan(in, &cur.Val)
		if i+1<n {
			cur.Next = &Node{}
			cur = cur.Next
		}
	}
	return head
}

func slove(list1 *Node, list2 *Node) *Node {
    dummy := &Node{}
    tail := dummy
    cur1, cur2 := list1, list2
    //一开始在双方都不是nil的情况下接后续节点
    for cur1 != nil && cur2 != nil {
        if cur1.Val < cur2.Val {
            tail.Next = cur1
            cur1 = cur1.Next
        } else {
            tail.Next = cur2
            cur2 = cur2.Next
        }
		//记得这个tail也要向后移动
        tail = tail.Next
    }
    
    // 当任意一方出现nil,连接剩余部分
    if cur1 != nil {
        tail.Next = cur1
    } else {
        tail.Next = cur2
    }
    
    return dummy.Next
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n1,n2 int
	if _, err := fmt.Fscan(in, &n1, &n2); err != nil {
		return 
	}
	heada := bulidlist(in,n1)
	headb := bulidlist(in,n2)
	head := slove(heada,headb)
	for cur:=head;cur!=nil;cur=cur.Next {
		fmt.Println(cur.Val)
	}
}

设链表长度为 m、n：时间复杂度 O(m+n)；空间复杂度 O(1)。

