同时遍历两个链表并维护进位 carry，逐位计算和并创建结果节点，直到链表和进位都处理完。

package main

import (
	"bufio"
	"fmt"
	"os"
)

type Node struct {
	Val  int
	Next *Node
}

func bulidlist(in *bufio.Reader, n int) *Node {
	if n == 0 {
		return nil
	}
	head := &Node{}
	cur := head
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &cur.Val)
		if i+1 < n {
			cur.Next = &Node{}
			cur = cur.Next
		}
	}
	return head
}

func slove(list1 *Node, list2 *Node) *Node {
	dummy := &Node{}
	tail := dummy
	carry := 0
	//这道题采取的方式是三个值谁有都行,内部再来逐一处理每一项
	for list1 != nil || list2 != nil || carry != 0 {
		//开头先处理carry
		sum := carry
		//再来处理list1
		if list1 != nil {
			sum += list1.Val
			list1 = list1.Next
		}
		//再来处理list2
		if list2 != nil {
			sum += list2.Val
			list2 = list2.Next
		}
		//最后计算节点信息
		carry = sum / 10
		tail.Next = &Node{Val: sum % 10}
		tail = tail.Next
	}
	return dummy.Next
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n1, n2 int
	if _, err := fmt.Fscan(in, &n1, &n2); err != nil {
		return
	}
	list1 := bulidlist(in, n1)
	list2 := bulidlist(in, n2)
	ans := slove(list1, list2)
	for cur := ans; cur != nil; cur = cur.Next {
		fmt.Printf("%d ", cur.Val)
	}
	fmt.Println()
}


设链表长度为 m、n：时间复杂度 O(max(m,n))；辅助空间 O(1)，结果链表空间 O(max(m,n))。

