type ListNode struct {
	Val  int
	Next *ListNode
}

func reverseKGroupReference(head *ListNode, k int) *ListNode {
	dummy := &ListNode{Next: head}
	groupPrev := dummy
	for {
		kth := groupPrev
		for i := 0; i < k && kth != nil; i++ {
			kth = kth.Next
		}
		if kth == nil {
			break
		}
		groupNext := kth.Next
		prev, cur := groupNext, groupPrev.Next
		for cur != groupNext {
			next := cur.Next
			cur.Next = prev
			prev = cur
			cur = next
		}
		oldStart := groupPrev.Next
		groupPrev.Next = kth
		groupPrev = oldStart
	}
	return dummy.Next
}

