func diameterOfBinaryTreeReference(root *TreeNode) int {
	best := 0
	var depth func(*TreeNode) int
	depth = func(node *TreeNode) int {
		if node == nil {
			return 0
		}
		left := depth(node.Left)
		right := depth(node.Right)
		if left+right > best {
			best = left + right
		}
		if left > right {
			return left + 1
		}
		return right + 1
	}
	depth(root)
	return best
}

