func combinationSumReference(candidates []int, target int) [][]int {
	sort.Ints(candidates)
	path := make([]int, 0)
	ans := make([][]int, 0)
	var dfs func(int, int)
	dfs = func(start, remain int) {
		if remain == 0 {
