func searchReference(nums []int, target int) int {
	n := len(nums)
	left, right := 0, n-1
	for left < right {
		mid := left + (right-left)/2
		if nums[mid] > nums[right] {
			left = mid + 1
		} else {
			right = mid
		}
	}
	pivot := left

	if target >= nums[pivot] && target <= nums[n-1] {
		left, right = pivot, n
	} else {
		left, right = 0, pivot
	}

	for left < right {
		mid := left + (right-left)/2
		if nums[mid] < target {
			left = mid + 1
		} else {
			right = mid
		}
	}

	if left < n && nums[left] == target {
		return left
	}
	return -1
}

