}

func topKFrequentReference(nums []int, k int) []int {
	count := make(map[int]int)
	for _, x := range nums {
		count[x]++
	}
	h := &freqMinHeap{}
	for num, freq := range count {
		if h.Len() < k {
			heap.Push(h, freqPair{num, freq})
		} else if freq > (*h)[0].freq {
			(*h)[0] = freqPair{num, freq}
			heap.Fix(h, 0)
		}
	}
	ans := make([]int, h.Len())
