func jumpReference(nums []int) int {
	if len(nums) <= 1 {
		return 0
	}
	steps := 0
	curEnd := 0
	farthest := 0
	for i := 0; i < len(nums)-1; i++ {
		if i+nums[i] > farthest {
			farthest = i + nums[i]
		}
		if i == curEnd {
			steps++
			curEnd = farthest
		}
	}
	return steps
}

