func wordBreakReference(s string, wordDict []string) bool {
	set := make(map[string]struct{}, len(wordDict))
	maxLen := 0
	for _, word := range wordDict {
		set[word] = struct{}{}
		if len(word) > maxLen {
			maxLen = len(word)
		}
	}

	dp := make([]bool, len(s)+1)
	dp[0] = true
	for i := 1; i <= len(s); i++ {
		start := i - maxLen
		if start < 0 {
			start = 0
		}
		for j := start; j < i; j++ {
			if dp[j] {
				if _, ok := set[s[j:i]]; ok {
					dp[i] = true
					break
				}
			}
		}
	}
	return dp[len(s)]
}

