func canPartitionReference(nums []int) bool {
	sum := 0
	for _, x := range nums {
		sum += x
	}
	if sum%2 == 1 {
		return false
	}

	target := sum / 2
	dp := make([]bool, target+1)
	dp[0] = true
	for _, x := range nums {
		for j := target; j >= x; j-- {
			dp[j] = dp[j] || dp[j-x]
		}
	}
	return dp[target]
}

