	}
	nums := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &nums[i])
	}
	fmt.Println(lengthOfLISReference(nums))
}

func lengthOfLISReference(nums []int) int {
	tails := make([]int, 0, len(nums))
	for _, x := range nums {
		idx := sort.SearchInts(tails, x)
		if idx == len(tails) {
			tails = append(tails, x)
		} else {
			tails[idx] = x
		}
	}
	return len(tails)
}

